    (452::BIGINT, 'Es un profesor super bueno, lo recomiendo mucho, se pasa bien y se aprende mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-05T00:00:00+00:00'::TIMESTAMPTZ, '8a957ce6de0ddb71aad29a5e47dc63743d2b63ae7aedb6b4f698c532d6ee8f41'::TEXT, ARRAY[3614]::BIGINT[]),
    (452::BIGINT, 'Es muy bueno explicando y es entretenido, las evaluaciones son senciilas, sin embargo a veces tiene cambios de humor repentinos y puede ser un poco grosero. Pero en general es un buen profesor'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-04T00:00:00+00:00'::TIMESTAMPTZ, '42d6f3097991baa454863e43c722bcedcd43b17e78c711c1abf3c37baf424b22'::TEXT, ARRAY[3614]::BIGINT[]),
    (452::BIGINT, 'Es un 20/10 como profe, es de los mejores profes de la escuela de produ. Sin pensarlo matricule con él, no se va a arrepentir, va a aprender demasiado y lo mejor de todo super bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'ebca4e70ab65fdb6f1c310e59e8446b80a313e6bad4a2582f95a09bfa3a864d1'::TEXT, ARRAY[1756]::BIGINT[]),
    (452::BIGINT, 'Si puede llevarlo con el no lo dude, es muy bueno y hace la clase muy entretenida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'a567ae50acc941a31f79649f0a9c75b8276bdbcc7f0b289f4ef3e27dbf415da1'::TEXT, ARRAY[3614]::BIGINT[]),
    (452::BIGINT, 'Las evaluaciones son sencillas y las clases bastante buenas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-29T00:00:00+00:00'::TIMESTAMPTZ, '53dcd57c0fb8824d769a918f2ca113943f90c519f0dca9520ba74ed4a049a2f9'::TEXT, ARRAY[1756]::BIGINT[]),
    (452::BIGINT, 'Sabe bastante de la materia, las clases son entretenidas y las evaluaciones son sencillas. Se aprende mucho en el curso'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-25T00:00:00+00:00'::TIMESTAMPTZ, 'eeaef5354f0896c7d82cc6b267e2c5b062c3e625e64b74f7dfa0dbaea0a4e276'::TEXT, ARRAY[3614]::BIGINT[]),
    (452::BIGINT, 'Muy bueno y súper entretenido'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-03T00:00:00+00:00'::TIMESTAMPTZ, '82d65f7b7d90427eb7aba559e52fe2fe29b2cfc6d048d69a48bbd129f44db2af'::TEXT, ARRAY[3614]::BIGINT[]),
    (452::BIGINT, 'Sabe mucho de metrologia, explica bien y deja evaluaciones sencillas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-03-10T00:00:00+00:00'::TIMESTAMPTZ, '55396096d9da968d1cd067a7ff66ebccd19734329633eb66828c17277f38684d'::TEXT, ARRAY[3614]::BIGINT[]),
    (452::BIGINT, 'Sabe mucho, explica bastante bien la materia aunque a veces sea medio enredada. Si llega a las clases y le pone atención va a pasar sin problemas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '1e8ebeaafbc0f7c5a695dcc029944151eff920d84a8f7168b1ddd6fdd6947daf'::TEXT, ARRAY[3594]::BIGINT[]),
    (452::BIGINT, 'El curso es muy fácil, pero el profe deja tareas aburridas todas las semanas que quitan tiempo, clases largas y el tiempo efectivo de la clases es muy poco, pero en sí se pasa con nota alta.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'c9d30065aecaea6b0ea879bd642d706ebe6dc4c4438e2d6565d0e00d916b3b84'::TEXT, ARRAY[1756]::BIGINT[]),
    (452::BIGINT, 'Explica bien pero es demasiado aburrido. Tiempo efectivo de clase es 30min o 45min a lo más. El resto del tiempo solo pierde el tiempo. De las clases más aburridas. Es facilísimo, se saca 95 o 100 uno. Es dificilísimo no dormirse, en especial a las 7:30am, pero no es mal profesor.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '1e013ea3cca1bdffa18334d18ad2f30a777a5e25bb851d31960c893b1ba4736f'::TEXT, ARRAY[1756]::BIGINT[]),
    (452::BIGINT, 'dems easy el profe, da "estrellas de talento" pero ni se ocupan para pasar sobrado el curso, igual los va a poner a pensar'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '756cb3e16554007cd306b1113adff0a1f17f5a3f8d689948f811f2a0950c1e18'::TEXT, ARRAY[3594]::BIGINT[]),
    (452::BIGINT, '(virtual) deja tareas todas las semanas (a veces más de una o dos), clases largas pero interesantes, el curso debe meterlo con un buen grupo de trabajo, muy accesible para consultas pero se contradice en sus respuestas. Si se aprende y la materia es interesante'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'bab934b68bb87c8e0b9257f5c1fd4261c254227492715d302481f4954c02474d'::TEXT, ARRAY[3614]::BIGINT[]),
    (452::BIGINT, 'La parte de metrología la domina bastante bien , pero en cuanto a normalización es confuso. En consulta dice cosas distintas a c/uno, entonces uno no sabe si realmente está entendiendo realmente la materia. Sin embargo, siempre nos motivó a dar más del 100%. Premia el esfuerzo y participación.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Da crédito extra']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '5363ee6af994a0bb5f9ce6c0f229d6c5eb3dddd57b52d3f646509d7daae1f90e'::TEXT, ARRAY[1756]::BIGINT[]),
    (452::BIGINT, 'Un gran agrandado que se nota que no prepara sus clases. En las clases parece mas interesado en hace su “stand-up comedy” que se basa en humillar a los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '690f9f9fd5f82e520a2082e4796fd21d06de202e5ff8c464cf837766399f7b53'::TEXT, ARRAY[3614]::BIGINT[]),
    (452::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '56f9db047c5856f7fa327fbf14aa88d93d35513a6d550de606a857cd7a88d93d'::TEXT, ARRAY[1756]::BIGINT[]),
    (452::BIGINT, 'En metro es buen profe, el curso es fácil en sí, el profe lo trata de explicar bien y dar ejemplos... Las clases son suuumamente largas. Califica suave'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'cc91ef8235aa211d90de5627fed9669699769ea13ab7ce57a4b700b1cf990dec'::TEXT, ARRAY[3614]::BIGINT[]),
    (452::BIGINT, 'Al inicio parece un buen profesor, pero conforme avanza el semestre se va viendo en realidad cómo es él. No soporta que lo contradigan, en muchos casos los exámenes y quices no son muy claros y cuando uno pregunta no responde y las clases son LARGAS.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2020-07-24T00:00:00+00:00'::TIMESTAMPTZ, '8b7459dd0e4186f19b3a464cd5ea0eaf409424b42ae6f9f1e93b399b2ae531db'::TEXT, ARRAY[3614, 3593]::BIGINT[]),
    (452::BIGINT, 'no se como habrá sido presencial, pero por zoom el mae hace clases largúisimas de puro relleno. Hizo lo que le dio la gana con la materia de calidad a veces hace lo que dice el libro a veces no...pero di digamos que entre las otras opciones es la menos mala'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-07-24T00:00:00+00:00'::TIMESTAMPTZ, '198bebf6098ee67cc8afa69616cd250809fd8cf8b5434117d2adec22d5cb46fa'::TEXT, ARRAY[3593, 3614]::BIGINT[]),
    (452::BIGINT, 'Pésimo, en realidad tiene demasiados errores y confusiones en los conceptos, es falso que sabe de calidad. En consulta dice una cosa y luego califica otra. Da materia que en el libro dice que está mal, y si uno lo corrige hace una pataleta y un berrinche de un niño de 5 años.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'fc19ea6d66f0562f78aaf4d21841c2515f15bcb8e69e6ac3bc10f6f90ae5546f'::TEXT, ARRAY[1757]::BIGINT[]),
